-- Retail Stock and Sales: database structure (PostgreSQL version of the program's SQLite database)
-- For pgAdmin's ERD: create an empty database, open the Query Tool, paste this whole file, Run (F5),
-- then right-click the database -> 'ERD For Database'. Tables only, no data.

CREATE SCHEMA IF NOT EXISTS retail_stock;
SET search_path TO retail_stock;

CREATE TABLE "attendance" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "employee_id" INTEGER NOT NULL,
    "date" TEXT NOT NULL,
    "time_in" TEXT NOT NULL,
    PRIMARY KEY ("id"),
    UNIQUE ("employee_id", "date")
);

CREATE TABLE "audit_log" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "at" TEXT NOT NULL,
    "user_id" INTEGER,
    "action" TEXT NOT NULL,
    "detail" TEXT,
    PRIMARY KEY ("id")
);

CREATE TABLE "bulk_order_items" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "order_id" INTEGER NOT NULL,
    "name" TEXT NOT NULL,
    "qty" DOUBLE PRECISION NOT NULL DEFAULT 0,
    "unit" TEXT,
    "price" DOUBLE PRECISION NOT NULL DEFAULT 0,
    "delivered" INTEGER NOT NULL DEFAULT 0,
    "item_id" INTEGER,
    "kg_per_unit" DOUBLE PRECISION,
    "stock_taken" DOUBLE PRECISION,
    PRIMARY KEY ("id")
);

CREATE TABLE "bulk_order_payments" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "order_id" INTEGER NOT NULL,
    "amount" DOUBLE PRECISION NOT NULL,
    "note" TEXT,
    "date" TEXT NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "bulk_order_runs" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "order_id" INTEGER,
    "transport_id" INTEGER,
    "trips" INTEGER NOT NULL DEFAULT 1,
    "date" TEXT,
    "driver_id" INTEGER,
    "done" INTEGER NOT NULL DEFAULT 0,
    "mode" TEXT,
    "carrier" TEXT,
    "carrier_cost" DOUBLE PRECISION,
    "purpose" TEXT,
    "place" TEXT,
    "note" TEXT,
    "time" TEXT,
    PRIMARY KEY ("id")
);

CREATE TABLE "bulk_orders" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "customer" TEXT NOT NULL,
    "start_date" TEXT,
    "end_date" TEXT,
    "status" TEXT NOT NULL DEFAULT 'active',
    "completed_date" TEXT,
    "created" TEXT,
    "address" TEXT,
    "charge_delivery" INTEGER,
    PRIMARY KEY ("id")
);

CREATE TABLE "cash_entries" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "date" TEXT NOT NULL,
    "direction" TEXT NOT NULL,
    "amount" DOUBLE PRECISION NOT NULL,
    "note" TEXT,
    PRIMARY KEY ("id")
);

CREATE TABLE "custom_items" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "custom_type_id" INTEGER NOT NULL,
    "name" TEXT NOT NULL,
    "amount" DOUBLE PRECISION NOT NULL DEFAULT 0,
    "basis" TEXT NOT NULL DEFAULT 'per_employee',
    "notes" TEXT,
    PRIMARY KEY ("id")
);

CREATE TABLE "custom_types" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "label" TEXT NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "delivery_drafts" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "receipt_id" INTEGER,
    "user_id" INTEGER,
    "created" TEXT,
    "status" TEXT NOT NULL DEFAULT 'new',
    "customer" TEXT,
    "address" TEXT,
    "delivery_date" TEXT,
    "data" TEXT,
    "order_id" INTEGER,
    "handled" TEXT,
    "image" TEXT,
    PRIMARY KEY ("id")
);

CREATE TABLE "employee_cash_advances" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "employee_id" INTEGER NOT NULL,
    "amount" DOUBLE PRECISION NOT NULL,
    "note" TEXT,
    "date" TEXT NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "employee_payments" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "employee_id" INTEGER NOT NULL,
    "kind" TEXT NOT NULL DEFAULT 'payroll',
    "amount" DOUBLE PRECISION NOT NULL,
    "note" TEXT,
    "date" TEXT NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "employees" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "name" TEXT NOT NULL,
    "position" TEXT,
    "rate_per_hour" DOUBLE PRECISION NOT NULL DEFAULT 0,
    "per_day_rate" DOUBLE PRECISION NOT NULL DEFAULT 0,
    "present_days" DOUBLE PRECISION NOT NULL DEFAULT 0,
    "absent_days" DOUBLE PRECISION NOT NULL DEFAULT 0,
    "overtime_hours" DOUBLE PRECISION NOT NULL DEFAULT 0,
    "notes" TEXT,
    "photo" TEXT,
    "user_id" INTEGER,
    "active" INTEGER NOT NULL DEFAULT 1,
    "created" TEXT,
    "temporary" INTEGER NOT NULL DEFAULT 0,
    "undertime_hours" DOUBLE PRECISION NOT NULL DEFAULT 0,
    "removed" TEXT,
    PRIMARY KEY ("id")
);

CREATE TABLE "items" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "name" TEXT NOT NULL,
    "unit" TEXT NOT NULL,
    "quantity" DOUBLE PRECISION NOT NULL,
    "sell_price" DOUBLE PRECISION NOT NULL,
    "cost_price" DOUBLE PRECISION NOT NULL,
    "product_id" INTEGER,
    "spec" TEXT,
    "level_a" DOUBLE PRECISION,
    "level_b" DOUBLE PRECISION,
    "level_c" DOUBLE PRECISION,
    "cost_auto" INTEGER NOT NULL DEFAULT 0,
    "qty_unknown" INTEGER NOT NULL DEFAULT 0,
    "deleted_at" TEXT,
    PRIMARY KEY ("id")
);

CREATE TABLE "maintenance_items" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "name" TEXT NOT NULL,
    "amount" DOUBLE PRECISION NOT NULL DEFAULT 0,
    "freq_value" INTEGER NOT NULL DEFAULT 1,
    "freq_unit" TEXT NOT NULL DEFAULT 'months',
    "last_paid" TEXT,
    "notes" TEXT,
    "start_date" TEXT,
    PRIMARY KEY ("id")
);

CREATE TABLE "maintenance_payments" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "item_id" INTEGER NOT NULL,
    "amount" DOUBLE PRECISION NOT NULL,
    "date" TEXT NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "obligation_payments" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "obligation_id" INTEGER NOT NULL,
    "amount" DOUBLE PRECISION NOT NULL,
    "note" TEXT,
    "date" TEXT NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "obligations" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "kind" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "party" TEXT,
    "start_date" TEXT,
    "end_date" TEXT,
    "freq_value" INTEGER NOT NULL DEFAULT 1,
    "freq_unit" TEXT NOT NULL DEFAULT 'months',
    "principal" DOUBLE PRECISION NOT NULL DEFAULT 0,
    "interest_rate" DOUBLE PRECISION NOT NULL DEFAULT 0,
    "final_payment" DOUBLE PRECISION NOT NULL DEFAULT 0,
    "status" TEXT NOT NULL DEFAULT 'active',
    "created" TEXT,
    PRIMARY KEY ("id")
);

CREATE TABLE "ocr_runs" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "created" TEXT,
    "device" TEXT,
    "model" TEXT,
    "max_side" INTEGER,
    "img_w" INTEGER,
    "img_h" INTEGER,
    "seconds" DOUBLE PRECISION,
    "lines" INTEGER,
    PRIMARY KEY ("id")
);

CREATE TABLE "pay_accounts" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "bank" TEXT NOT NULL,
    "nickname" TEXT,
    "holder" TEXT,
    "last4" TEXT,
    "opening" DOUBLE PRECISION NOT NULL DEFAULT 0,
    "opening_date" TEXT,
    "created" TEXT,
    PRIMARY KEY ("id")
);

CREATE TABLE "pay_entries" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "account_id" INTEGER,
    "direction" TEXT NOT NULL,
    "amount" DOUBLE PRECISION NOT NULL,
    "date" TEXT NOT NULL,
    "party" TEXT,
    "ref" TEXT,
    "note" TEXT,
    "order_id" INTEGER,
    "order_payment_id" INTEGER,
    "photo" TEXT,
    "created" TEXT,
    "method" TEXT,
    PRIMARY KEY ("id")
);

CREATE TABLE "positions" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "name" TEXT NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "priority_dismissed" (
    "key" TEXT,
    "dismissed_at" TEXT,
    PRIMARY KEY ("key")
);

CREATE TABLE "products" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "name" TEXT NOT NULL,
    "icon_key" TEXT,
    "created" TEXT,
    "image" TEXT,
    PRIMARY KEY ("id")
);

CREATE TABLE "receipt_lines" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "receipt_id" INTEGER NOT NULL,
    "ocr_text" TEXT,
    "item_id" INTEGER NOT NULL,
    "score" DOUBLE PRECISION,
    "qty" DOUBLE PRECISION,
    "verified" INTEGER NOT NULL DEFAULT 0,
    "sold" INTEGER NOT NULL DEFAULT 0,
    "sale_id" INTEGER,
    "price" DOUBLE PRECISION,
    "item_text" TEXT,
    PRIMARY KEY ("id")
);

CREATE TABLE "receipt_unmatched" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "receipt_id" INTEGER NOT NULL,
    "ocr_text" TEXT,
    "item_text" TEXT,
    "qty" DOUBLE PRECISION,
    "price" DOUBLE PRECISION,
    "unit" TEXT,
    "req_name" TEXT,
    "req_price" DOUBLE PRECISION,
    "req_qty" DOUBLE PRECISION,
    "req_unit" TEXT,
    "req_by" INTEGER,
    "req_at" TEXT,
    "req_stock" DOUBLE PRECISION,
    PRIMARY KEY ("id")
);

CREATE TABLE "receipts" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "user_id" INTEGER NOT NULL,
    "client_id" TEXT,
    "image" TEXT NOT NULL,
    "status" TEXT NOT NULL,
    "error" TEXT,
    "created" TEXT,
    "started" TEXT,
    "finished" TEXT,
    "seconds" DOUBLE PRECISION,
    "device" TEXT,
    "model" TEXT,
    "pay_mode" TEXT,
    "pay_note" TEXT,
    "pay_sure" INTEGER,
    PRIMARY KEY ("id"),
    UNIQUE ("user_id", "client_id")
);

CREATE TABLE "run_crew" (
    "run_id" INTEGER NOT NULL,
    "employee_id" INTEGER NOT NULL,
    PRIMARY KEY ("run_id", "employee_id")
);

CREATE TABLE "sale_items" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "sale_id" INTEGER,
    "item_id" INTEGER,
    "qty" DOUBLE PRECISION,
    "sell_price" DOUBLE PRECISION,
    "cost_price" DOUBLE PRECISION,
    PRIMARY KEY ("id")
);

CREATE TABLE "sales" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "created" TEXT,
    "image" TEXT,
    "total" DOUBLE PRECISION,
    "profit" DOUBLE PRECISION,
    "user_id" INTEGER,
    "pay_mode" TEXT,
    "pay_note" TEXT,
    PRIMARY KEY ("id")
);

CREATE TABLE "sessions" (
    "token_hash" TEXT,
    "user_id" INTEGER NOT NULL,
    "created" TEXT,
    "expires" TEXT NOT NULL,
    "last_seen" TEXT,
    "kind" TEXT NOT NULL DEFAULT 'phone',
    PRIMARY KEY ("token_hash")
);

CREATE TABLE "settings" (
    "key" TEXT,
    "value" TEXT,
    PRIMARY KEY ("key")
);

CREATE TABLE "stock_purchases" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "item_id" INTEGER NOT NULL,
    "qty" DOUBLE PRECISION NOT NULL,
    "unit_cost" DOUBLE PRECISION NOT NULL,
    "standard_cost" DOUBLE PRECISION NOT NULL,
    "savings" DOUBLE PRECISION NOT NULL,
    "source" TEXT NOT NULL DEFAULT 'external',
    "supplier" TEXT,
    "bought_at" TEXT NOT NULL,
    "note" TEXT,
    PRIMARY KEY ("id")
);

CREATE TABLE "supply_sourcing" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "item_id" INTEGER NOT NULL,
    "source" TEXT NOT NULL,
    "unit_cost" DOUBLE PRECISION NOT NULL DEFAULT 0,
    "transfer_cost" DOUBLE PRECISION NOT NULL DEFAULT 0,
    "maintenance_cost" DOUBLE PRECISION NOT NULL DEFAULT 0,
    "updated" TEXT,
    PRIMARY KEY ("id"),
    UNIQUE ("item_id", "source")
);

CREATE TABLE "transports" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "truck_name" TEXT NOT NULL,
    "plate" TEXT,
    "capacity" TEXT,
    "cost" DOUBLE PRECISION NOT NULL DEFAULT 0,
    "created" TEXT,
    "capacity_value" DOUBLE PRECISION,
    "capacity_unit" TEXT,
    PRIMARY KEY ("id")
);

CREATE TABLE "units" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "name" TEXT NOT NULL,
    "to_kg" DOUBLE PRECISION,
    PRIMARY KEY ("id")
);

CREATE TABLE "user_activity" (
    "user_id" INTEGER NOT NULL,
    "date" TEXT NOT NULL,
    "first_seen" TEXT NOT NULL,
    "last_seen" TEXT NOT NULL,
    PRIMARY KEY ("user_id", "date")
);

CREATE TABLE "users" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "username" TEXT NOT NULL,
    "display_name" TEXT,
    "password_hash" TEXT NOT NULL,
    "avatar" TEXT,
    "active" INTEGER NOT NULL DEFAULT 1,
    "created" TEXT,
    "is_admin" INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);

CREATE TABLE "work_hours" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "employee_id" INTEGER NOT NULL,
    "date" TEXT NOT NULL,
    "ot_hours" DOUBLE PRECISION NOT NULL DEFAULT 0,
    "ut_hours" DOUBLE PRECISION NOT NULL DEFAULT 0,
    "note" TEXT,
    PRIMARY KEY ("id"),
    UNIQUE ("employee_id", "date")
);

-- links between the tables (shown as lines in the ERD)
ALTER TABLE "attendance" ADD CONSTRAINT "fk_attendance_employee_id" FOREIGN KEY ("employee_id") REFERENCES "employees" ("id");
ALTER TABLE "audit_log" ADD CONSTRAINT "fk_audit_log_user_id" FOREIGN KEY ("user_id") REFERENCES "users" ("id");
ALTER TABLE "bulk_order_items" ADD CONSTRAINT "fk_bulk_order_items_order_id" FOREIGN KEY ("order_id") REFERENCES "bulk_orders" ("id");
ALTER TABLE "bulk_order_items" ADD CONSTRAINT "fk_bulk_order_items_item_id" FOREIGN KEY ("item_id") REFERENCES "items" ("id");
ALTER TABLE "bulk_order_payments" ADD CONSTRAINT "fk_bulk_order_payments_order_id" FOREIGN KEY ("order_id") REFERENCES "bulk_orders" ("id");
ALTER TABLE "bulk_order_runs" ADD CONSTRAINT "fk_bulk_order_runs_order_id" FOREIGN KEY ("order_id") REFERENCES "bulk_orders" ("id");
ALTER TABLE "bulk_order_runs" ADD CONSTRAINT "fk_bulk_order_runs_transport_id" FOREIGN KEY ("transport_id") REFERENCES "transports" ("id");
ALTER TABLE "bulk_order_runs" ADD CONSTRAINT "fk_bulk_order_runs_driver_id" FOREIGN KEY ("driver_id") REFERENCES "employees" ("id");
ALTER TABLE "custom_items" ADD CONSTRAINT "fk_custom_items_custom_type_id" FOREIGN KEY ("custom_type_id") REFERENCES "custom_types" ("id");
ALTER TABLE "delivery_drafts" ADD CONSTRAINT "fk_delivery_drafts_receipt_id" FOREIGN KEY ("receipt_id") REFERENCES "receipts" ("id");
ALTER TABLE "delivery_drafts" ADD CONSTRAINT "fk_delivery_drafts_user_id" FOREIGN KEY ("user_id") REFERENCES "users" ("id");
ALTER TABLE "delivery_drafts" ADD CONSTRAINT "fk_delivery_drafts_order_id" FOREIGN KEY ("order_id") REFERENCES "bulk_orders" ("id");
ALTER TABLE "employee_cash_advances" ADD CONSTRAINT "fk_employee_cash_advances_employee_id" FOREIGN KEY ("employee_id") REFERENCES "employees" ("id");
ALTER TABLE "employee_payments" ADD CONSTRAINT "fk_employee_payments_employee_id" FOREIGN KEY ("employee_id") REFERENCES "employees" ("id");
ALTER TABLE "employees" ADD CONSTRAINT "fk_employees_user_id" FOREIGN KEY ("user_id") REFERENCES "users" ("id");
ALTER TABLE "items" ADD CONSTRAINT "fk_items_product_id" FOREIGN KEY ("product_id") REFERENCES "products" ("id");
ALTER TABLE "maintenance_payments" ADD CONSTRAINT "fk_maintenance_payments_item_id" FOREIGN KEY ("item_id") REFERENCES "maintenance_items" ("id");
ALTER TABLE "obligation_payments" ADD CONSTRAINT "fk_obligation_payments_obligation_id" FOREIGN KEY ("obligation_id") REFERENCES "obligations" ("id");
ALTER TABLE "pay_entries" ADD CONSTRAINT "fk_pay_entries_account_id" FOREIGN KEY ("account_id") REFERENCES "pay_accounts" ("id");
ALTER TABLE "pay_entries" ADD CONSTRAINT "fk_pay_entries_order_id" FOREIGN KEY ("order_id") REFERENCES "bulk_orders" ("id");
ALTER TABLE "receipt_lines" ADD CONSTRAINT "fk_receipt_lines_receipt_id" FOREIGN KEY ("receipt_id") REFERENCES "receipts" ("id");
ALTER TABLE "receipt_lines" ADD CONSTRAINT "fk_receipt_lines_item_id" FOREIGN KEY ("item_id") REFERENCES "items" ("id");
ALTER TABLE "receipt_lines" ADD CONSTRAINT "fk_receipt_lines_sale_id" FOREIGN KEY ("sale_id") REFERENCES "sales" ("id");
ALTER TABLE "receipt_unmatched" ADD CONSTRAINT "fk_receipt_unmatched_receipt_id" FOREIGN KEY ("receipt_id") REFERENCES "receipts" ("id");
ALTER TABLE "receipts" ADD CONSTRAINT "fk_receipts_user_id" FOREIGN KEY ("user_id") REFERENCES "users" ("id");
ALTER TABLE "run_crew" ADD CONSTRAINT "fk_run_crew_run_id" FOREIGN KEY ("run_id") REFERENCES "bulk_order_runs" ("id");
ALTER TABLE "run_crew" ADD CONSTRAINT "fk_run_crew_employee_id" FOREIGN KEY ("employee_id") REFERENCES "employees" ("id");
ALTER TABLE "sale_items" ADD CONSTRAINT "fk_sale_items_sale_id" FOREIGN KEY ("sale_id") REFERENCES "sales" ("id");
ALTER TABLE "sale_items" ADD CONSTRAINT "fk_sale_items_item_id" FOREIGN KEY ("item_id") REFERENCES "items" ("id");
ALTER TABLE "sales" ADD CONSTRAINT "fk_sales_user_id" FOREIGN KEY ("user_id") REFERENCES "users" ("id");
ALTER TABLE "sessions" ADD CONSTRAINT "fk_sessions_user_id" FOREIGN KEY ("user_id") REFERENCES "users" ("id");
ALTER TABLE "stock_purchases" ADD CONSTRAINT "fk_stock_purchases_item_id" FOREIGN KEY ("item_id") REFERENCES "items" ("id");
ALTER TABLE "supply_sourcing" ADD CONSTRAINT "fk_supply_sourcing_item_id" FOREIGN KEY ("item_id") REFERENCES "items" ("id");
ALTER TABLE "user_activity" ADD CONSTRAINT "fk_user_activity_user_id" FOREIGN KEY ("user_id") REFERENCES "users" ("id");
ALTER TABLE "work_hours" ADD CONSTRAINT "fk_work_hours_employee_id" FOREIGN KEY ("employee_id") REFERENCES "employees" ("id");
